window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-451fd9f7db739130"]={"versions": [{"id": "FIG-451fd9f7db739130", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition grundlegender Daten- und Konfigurationstypen des BSW-Moduls <code>J1939Dcm</code> (SAE J1939 Diagnostic Communication Manager) innerhalb des Pakets <code>J1939Dcm_Types</code> im AUTOSAR-Basissoftware-Architekturkontext.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind zwei getrennte Typdefinitionen ohne explizite Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>J1939Dcm_ConfigType</code>: Strukturtyp (<code>«structure»</code>), dessen Inhalt als implementationsspezifisch deklariert ist (<code>+ implementation specific</code>).\n</li><li><code>J1939Dcm_StateType</code>: Aufzählungstyp (<code>«enumeration»</code>), der über den Wertebereichs-Stereotyp <code>«range»</code> zwei Zustände definiert: <code>J1939DCM_STATE_ONLINE = 0</code> und <code>J1939DCM_STATE_OFFLINE = 1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Klassendiagramm ohne dynamische Interaktionen oder Sequenzabläufe. Die Typen definieren die Datenbasis für die Initialisierungskonfiguration sowie den Betriebs- bzw. Kommunikationszustand des Moduls.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Typdefinitionen für Schnittstellen und Konfiguration des SAE J1939 DCM:</p>\n<ul class=\"fig-list\"><li><code>J1939Dcm_ConfigType</code> dient als Argument für Initialisierungsfunktionen (z. B. <code>J1939Dcm_Init</code>), wobei die konkreten Member vom BSW-Stack-Hersteller festgelegt werden.\n</li><li><code>J1939Dcm_StateType</code> dient als Rückgabe- oder Zustandsparameter für API-Funktionen zur Statusabfrage oder Modusverwaltung mit den festen Werten <code>0</code> (Online) und <code>1</code> (Offline).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ffa89cd5e0ca22a3", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition grundlegender Daten- und Konfigurationstypen des BSW-Moduls <code>J1939Dcm</code> (SAE J1939 Diagnostic Communication Manager) innerhalb des Pakets <code>J1939Dcm_Types</code> im AUTOSAR-Basissoftware-Architekturkontext.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind zwei getrennte Typdefinitionen ohne explizite Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>J1939Dcm_ConfigType</code>: Strukturtyp (<code>«structure»</code>), dessen Inhalt als implementationsspezifisch deklariert ist (<code>+ implementation specific</code>).\n</li><li><code>J1939Dcm_StateType</code>: Aufzählungstyp (<code>«enumeration»</code>), der über den Wertebereichs-Stereotyp <code>«range»</code> zwei Zustände in hexadezimaler Notation definiert: <code>J1939DCM_STATE_ONLINE = 0x00</code> und <code>J1939DCM_STATE_OFFLINE = 0x01</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Klassendiagramm ohne dynamische Interaktionen oder Sequenzabläufe. Die Typen definieren die Datenbasis für die Initialisierungskonfiguration sowie den Betriebs- bzw. Kommunikationszustand des Moduls.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Typdefinitionen für Schnittstellen und Konfiguration des SAE J1939 DCM:</p>\n<ul class=\"fig-list\"><li><code>J1939Dcm_ConfigType</code> dient als Argument für Initialisierungsfunktionen (z. B. <code>J1939Dcm_Init</code>), wobei die konkreten Member vom BSW-Stack-Hersteller festgelegt werden.\n</li><li><code>J1939Dcm_StateType</code> dient als Rückgabe- oder Zustandsparameter für API-Funktionen zur Statusabfrage oder Modusverwaltung mit den festen Werten <code>0x00</code> (Online) und <code>0x01</code> (Offline).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d030a0d9b099f20b", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition grundlegender Daten- und Konfigurationstypen des BSW-Moduls <code>J1939Dcm</code> (SAE J1939 Diagnostic Communication Manager) innerhalb des Pakets <code>J1939Dcm_Types</code> im AUTOSAR-Basissoftware-Architekturkontext.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind zwei getrennte Typdefinitionen ohne explizite Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>J1939Dcm_ConfigType</code>: Strukturtyp (<code>«structure»</code>), dessen Inhalt als implementationsspezifisch deklariert ist (<code>+ implementation specific</code>).\n</li><li><code>J1939Dcm_StateType</code>: Aufzählungstyp (<code>«enumeration»</code>), der über den Wertebereichs-Stereotyp <code>«range»</code> zwei Zustände in hexadezimaler Notation definiert: <code>J1939DCM_STATE_ONLINE = 0x00</code> und <code>J1939DCM_STATE_OFFLINE = 0x01</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Klassendiagramm ohne dynamische Interaktionen oder Sequenzabläufe. Die Typen definieren die Datenbasis für die Initialisierungskonfiguration sowie den Betriebs- bzw. Kommunikationszustand des Moduls.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Typdefinitionen für Schnittstellen und Konfiguration des SAE J1939 DCM:</p>\n<ul class=\"fig-list\"><li><code>J1939Dcm_ConfigType</code> dient als Argument für Initialisierungsfunktionen (z. B. <code>J1939Dcm_Init</code>), wobei die konkreten Member vom BSW-Stack-Hersteller festgelegt werden.\n</li><li><code>J1939Dcm_StateType</code> dient als Rückgabe- oder Zustandsparameter für API-Funktionen zur Statusabfrage oder Modusverwaltung mit den festen Werten <code>0x00</code> (Online) und <code>0x01</code> (Offline).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-dc31c51a34cbb125", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition grundlegender Daten- und Konfigurationstypen des BSW-Moduls <code>J1939Dcm</code> (SAE J1939 Diagnostic Communication Manager) innerhalb des Pakets <code>J1939Dcm_Types</code> im AUTOSAR-Basissoftware-Architekturkontext.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind zwei getrennte Typdefinitionen ohne explizite Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>J1939Dcm_ConfigType</code>: Strukturtyp (<code>«structure»</code>), gekennzeichnet mit dem Stereotyp <code>«bswNoModeledType»</code> für das implementationsspezifische Element <code>+ implementation specific</code>.\n</li><li><code>J1939Dcm_StateType</code>: Aufzählungstyp (<code>«enumeration»</code>), der über den Wertebereichs-Stereotyp <code>«range»</code> zwei Zustände in hexadezimaler Notation definiert: <code>J1939DCM_STATE_ONLINE = 0x00</code> und <code>J1939DCM_STATE_OFFLINE = 0x01</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Klassendiagramm ohne dynamische Interaktionen oder Sequenzabläufe. Die Typen definieren die Datenbasis für die Initialisierungskonfiguration sowie den Betriebs- bzw. Kommunikationszustand des Moduls.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Typdefinitionen für Schnittstellen und Konfiguration des SAE J1939 DCM:</p>\n<ul class=\"fig-list\"><li><code>J1939Dcm_ConfigType</code> ist mit dem Stereotyp <code>«bswNoModeledType»</code> versehen, was dokumentiert, dass die Struktur nicht im formalen AUTOSAR-Metamodell ausmodelliert ist, sondern implementierungsspezifisch im C-Header definiert wird.\n</li><li><code>J1939Dcm_StateType</code> dient als Rückgabe- oder Zustandsparameter für API-Funktionen zur Statusabfrage oder Modusverwaltung mit den festen Werten <code>0x00</code> (Online) und <code>0x01</code> (Offline).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-412272557293ab90", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition grundlegender Daten- und Konfigurationstypen des BSW-Moduls <code>J1939Dcm</code> (SAE J1939 Diagnostic Communication Manager) innerhalb des Pakets <code>J1939Dcm_Types</code> im AUTOSAR-Basissoftware-Architekturkontext.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind zwei getrennte Typdefinitionen ohne explizite Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>J1939Dcm_ConfigType</code>: Strukturtyp (<code>«structure»</code>), gekennzeichnet mit dem Stereotyp <code>«bswNoModeledType»</code> für das implementationsspezifische Element <code>+ implementation specific</code>.\n</li><li><code>J1939Dcm_StateType</code>: Aufzählungstyp (<code>«enumeration»</code>), der über den Wertebereichs-Stereotyp <code>«range»</code> zwei Zustände in hexadezimaler Notation definiert: <code>J1939DCM_STATE_ONLINE = 0x00</code> und <code>J1939DCM_STATE_OFFLINE = 0x01</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Klassendiagramm ohne dynamische Interaktionen oder Sequenzabläufe. Die Typen definieren die Datenbasis für die Initialisierungskonfiguration sowie den Betriebs- bzw. Kommunikationszustand des Moduls.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Typdefinitionen für Schnittstellen und Konfiguration des SAE J1939 DCM:</p>\n<ul class=\"fig-list\"><li><code>J1939Dcm_ConfigType</code> ist mit dem Stereotyp <code>«bswNoModeledType»</code> versehen, was dokumentiert, dass die Struktur nicht im formalen AUTOSAR-Metamodell ausmodelliert ist, sondern implementierungsspezifisch im C-Header definiert wird.\n</li><li><code>J1939Dcm_StateType</code> dient als Rückgabe- oder Zustandsparameter für API-Funktionen zur Statusabfrage oder Modusverwaltung mit den festen Werten <code>0x00</code> (Online) und <code>0x01</code> (Offline).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ccd65e1de1a8e211", "releases": ["R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition grundlegender Daten- und Konfigurationstypen des BSW-Moduls <code>J1939Dcm</code> (SAE J1939 Diagnostic Communication Manager) innerhalb des Pakets <code>J1939Dcm_Types</code> im AUTOSAR-Basissoftware-Architekturkontext.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind zwei getrennte Typdefinitionen ohne explizite Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>J1939Dcm_ConfigType</code>: Strukturtyp (<code>«structure»</code>), gekennzeichnet mit dem Stereotyp <code>«bswNoModeledType»</code> für das implementationsspezifische Element <code>+ implementation specific</code>.\n</li><li><code>J1939Dcm_StateType</code>: Aufzählungstyp (<code>«enumeration»</code>), der zwei Zustände in hexadezimaler Notation aufführt: <code>J1939DCM_STATE_ONLINE = 0x00</code> und <code>J1939DCM_STATE_OFFLINE = 0x01</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Klassendiagramm ohne dynamische Interaktionen oder Sequenzabläufe. Die Typen definieren die Datenbasis für die Initialisierungskonfiguration sowie den Betriebs- bzw. Kommunikationszustand des Moduls.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Typdefinitionen für Schnittstellen und Konfiguration des SAE J1939 DCM:</p>\n<ul class=\"fig-list\"><li><code>J1939Dcm_ConfigType</code> ist mit dem Stereotyp <code>«bswNoModeledType»</code> versehen, was dokumentiert, dass die Struktur nicht im formalen AUTOSAR-Metamodell ausmodelliert ist, sondern implementierungsspezifisch im C-Header definiert wird.\n</li><li><code>J1939Dcm_StateType</code> dient als Rückgabe- oder Zustandsparameter für API-Funktionen zur Statusabfrage oder Modusverwaltung mit den festen Werten <code>0x00</code> (Online) und <code>0x01</code> (Offline).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-451fd9f7db739130", "to": "FIG-ffa89cd5e0ca22a3", "fr": "R4.2.2", "tr": "R4.3.1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>J1939Dcm_StateType</code>: Werte der Enumerationselemente von dezimaler Schreibweise (<code>0</code>, <code>1</code>) auf hexadezimale Schreibweise (<code>0x00</code>, <code>0x01</code>) umgestellt.\n</li><li><code>J1939Dcm_StateType</code>: Leerzeichen nach dem Paketbezeichner <code>J1939Dcm_Types::</code> im Klassenheader entfernt.\n</li></ul>"}, {"from": "FIG-ffa89cd5e0ca22a3", "to": "FIG-d030a0d9b099f20b", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d030a0d9b099f20b", "to": "FIG-dc31c51a34cbb125", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>J1939Dcm_ConfigType</code>: Dem Attributbereich bzw. dem Attribut <code>+ implementation specific</code> wurde der Stereotyp <code>«bswNoModeledType»</code> vorangestellt.\n</li></ul>"}, {"from": "FIG-dc31c51a34cbb125", "to": "FIG-412272557293ab90", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-412272557293ab90", "to": "FIG-ccd65e1de1a8e211", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>J1939Dcm_StateType</code>: Stereotyp <code>«range»</code> vor den Enumerationswerten <code>J1939DCM_STATE_ONLINE = 0x00</code> und <code>J1939DCM_STATE_OFFLINE = 0x01</code> entfernt.\n</li></ul>"}]};
